{
  "technical_and_design_decisions": [
    "All externalized utility libraries (protoutil, BCCSP, MSP, discovery client) will be hosted in a new standalone fabric-lib-go repository to enable independent versioning and reuse by downstream projects like the Fabric Go SDK.",
    "Refactored statebased and entities packages will only import the already externalized fabric-protos-go package and standard Go libraries, eliminating all internal Hyperledger Fabric package dependencies as required by U1 and U2.",
    "Externalized libraries will maintain 100% API compatibility with their existing internal Fabric counterparts to avoid breaking changes for existing downstream users, including the Go SDK's current internal copied implementations.",
    "The marbles02_private tutorial update will only modify the documentation for the MARBLE environment variable export command, adding the tr -d \\\\ step to strip Windows-style line endings that cause JSON parsing errors.",
    "All refactoring and externalization work will be validated using the existing comprehensive test suites for all affected packages to ensure no functional regressions are introduced."
  ],
  "assumptions": [
    "We have necessary write access to the core Hyperledger Fabric repository, fabric-samples repository, and permissions to create the new fabric-lib-go repository under the Hyperledger GitHub organization.",
    "The existing internal copies of protoutil, BCCSP, MSP, and discovery client in the Fabric Go SDK can be replaced with the externalized libraries without requiring changes to the SDK's public API, due to maintained backward compatibility.",
    "The JSON parsing error in the marbles02_private tutorial is exclusively caused by Windows-style line endings in the base64-encoded JSON string, and adding the tr -d \\\\ command resolves the issue for all affected Windows host environments.",
    "The fabric-protos-go repository containing externalized protobuf definitions is already available and stable, so no work is needed to externalize protobuf dependencies as part of this increment.",
    "Existing test suites for all affected packages (statebased, entities, protoutil, BCCSP, MSP, discovery) are comprehensive enough to catch regressions from the refactoring and externalization work."
  ],
  "activities": [
    {
      "activity_id": "A0",
      "activity_name": "Setup fabric-lib-go repository and CI/CD",
      "activity_description": "Create the new standalone fabric-lib-go repository under the Hyperledger organization, configure the correct Go module path, set up CI/CD pipelines for automated testing and module publishing, and align contribution guidelines with existing Hyperledger Fabric standards.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A1",
      "activity_name": "Refactor statebased package to remove non-proto fabric dependencies",
      "activity_description": "Analyze current dependencies of core/chaincode/shim/ext/statebased, remove imports of fabric/comm, fabric/protoutil, pkg/errors, and all transitive fabric dependencies (bccsp, common/cauthdsl, etc.), replace removed functionality with equivalents from externalized fabric-lib-go libraries or standard Go libraries, ensure only fabric protos remain as fabric imports, run existing statebased package tests to verify no regressions.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor entities package to remove all fabric dependencies",
      "activity_description": "Analyze current dependencies of core/chaincode/shim/ext/entities/..., remove all imports of fabric packages (bccsp, common/flogging, etc.), replace removed functionality with standard Go or externalized library equivalents, run existing entities package tests to verify no regressions.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Update marbles02_private tutorial documentation",
      "activity_description": "Locate the marbles02_private chaincode tutorial in the fabric-samples repository, add the suggested tr -d \\\\ command to the MARBLE environment variable export example to prevent JSON parsing errors on Windows host systems, test the updated export command in the described Windows 7 host + Ubuntu VM environment to confirm the error is resolved.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize protoutil package to fabric-lib-go",
      "activity_description": "Extract the protoutil package from the core Fabric repository into the pre-configured fabric-lib-go repository, update all internal Fabric core references to use the external protoutil module, maintain full backward API compatibility with the existing internal protoutil package, run all protoutil and dependent Fabric component tests to verify no regressions.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize BCCSP package to fabric-lib-go",
      "activity_description": "Extract the BCCSP package and all subpackages (bccsp, factory, idemix, idemix/bridge, idemix/handlers, signer, sw, utils) from core Fabric into fabric-lib-go, maintain API compatibility with the existing internal BCCSP implementation used by the Go SDK, update all internal Fabric core references to use the external BCCSP module, run all BCCSP and dependent tests to verify no regressions.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize MSP package to fabric-lib-go",
      "activity_description": "Extract the MSP package and related subpackages from core Fabric into fabric-lib-go, maintain API compatibility with the existing internal MSP implementation used by the Go SDK, update all internal Fabric core references to use the external MSP module, run all MSP and dependent tests to verify no regressions.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize discovery client package to fabric-lib-go",
      "activity_description": "Extract the discovery client package from core Fabric into fabric-lib-go, maintain API compatibility with the existing internal discovery client used by the Go SDK, update all internal Fabric core references to use the external discovery module, run all discovery client and dependent tests to verify no regressions.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 144
  }
}

